+/* Demo logic only: these thresholds do not establish fire protection or
+ * validated dry-boil detection. Temperatures are milli-degrees Celsius (mC).
+ * Use a local monotonic millisecond clock, not wall time or a remote clock. */
+#define KITCHEN_RISK_HISTORY_CAPACITY 32u
+#define KITCHEN_RISK_RATE_WINDOW_MS 5000u
+#define KITCHEN_RISK_MIN_TEMP_MC (-70000)
+#define KITCHEN_RISK_MAX_TEMP_MC 380000
+
+typedef enum {
+    KITCHEN_RISK_IDLE = 0,
+    KITCHEN_RISK_WAITING,
+    KITCHEN_RISK_MONITORING,
+    KITCHEN_RISK_WARNING,
+    KITCHEN_RISK_ALARM
+} kitchen_risk_state_t;
+
+enum {
+    KITCHEN_RISK_FAULT_NO_DATA = 1u << 0,
+    KITCHEN_RISK_FAULT_SENSOR = 1u << 1,
+    KITCHEN_RISK_FAULT_STALE = 1u << 2
+};
+
+typedef struct {
+    int32_t warning_mc;
