+    int32_t rate_warning_mc_per_s;
+    uint32_t warning_hold_ms;
+    uint32_t alarm_hold_ms;
+    uint32_t reset_cool_ms;
+    uint32_t data_timeout_ms;
+    uint32_t mute_ms;
+    uint8_t recovery_samples;
+} kitchen_risk_config_t;
+
+typedef struct {
+    kitchen_risk_state_t state;
