+    int32_t rate_mc_per_s;
+    uint32_t sample_age_ms; /* UINT32_MAX when no valid sample has arrived. */
+} kitchen_risk_snapshot_t;
+
+typedef struct {
+    uint64_t at_ms;
+    int32_t temp_mc;
+} kitchen_risk_history_entry_t;
+
+/* Instance storage is public to permit static allocation on an MCU. Treat
+ * every field as private; use the functions below to inspect or change it. */
+typedef struct {
+    kitchen_risk_config_t config;
