+/* Defaults: DEMO 35 C warning / 45 C alarm / below 32 C for reset,
+ * 1 s confirmation, 5 s cool-down, 3 s stale timeout, 30 s mute,
+ * 3 consecutive valid samples to recover. Intended sampling rate: 2 Hz. */
+void kitchen_risk_default_config(kitchen_risk_config_t *config);
+bool kitchen_risk_init(kitchen_risk_t *risk,
+                       const kitchen_risk_config_t *config);
+
+/* Feed ONLY new telemetry frames, after checking their sequence number.
+ * Invalid frames may be reported with valid=false (temp_mc is then ignored).
+ * A valid sample must also be in the MLX90614 object-temperature range.
