+    CHECK(!kd_parse_temperature(too_long, sizeof(too_long), &frame));
+    CHECK(!kd_parse_temperature(NULL, 10u, &frame));
+    CHECK(!kd_parse_temperature("KD1 T 1 2 3 1 20000 20000\n", 28u, NULL));
+}
+
+static void test_partial_and_concatenated_lines(void)
+{
+    const char *first = "KD1 T 10 1 500 1 25000 24000\n";
+    const char *second = "KD1 T 10 2 1000 1 26000 24000\r\n";
+    kd_line_buffer_t buffer;
+    kd_temperature_t frame;
+    size_t i;
+    kd_line_init(&buffer);
+    for (i = 0u; i < 9u; ++i) {
+        CHECK(kd_line_feed(&buffer, first[i]) == KD_LINE_NONE);
+    }
+    CHECK(buffer.length == 9u);
+    for (; first[i] != '\0'; ++i) {
+        const kd_line_result_t result = kd_line_feed(&buffer, first[i]);
+        CHECK(result == (first[i] == '\n' ? KD_LINE_COMPLETE : KD_LINE_NONE));
+    }
+    CHECK(kd_parse_temperature(buffer.line, buffer.length, &frame));
+    CHECK(frame.seq == 1u && frame.object_mc == 25000);
+    for (i = 0u; second[i] != '\0'; ++i) {
+        const kd_line_result_t result = kd_line_feed(&buffer, second[i]);
+        CHECK(result == (second[i] == '\n' ? KD_LINE_COMPLETE : KD_LINE_NONE));
+    }
+    CHECK(kd_parse_temperature(buffer.line, buffer.length, &frame));
+    CHECK(frame.seq == 2u && frame.object_mc == 26000);
+}
+
+static void test_oversize_discard_and_boundaries(void)
+{
+    kd_line_buffer_t buffer;
+    kd_temperature_t frame;
+    const char *valid = "KD1 T 1 1 0 1 25000 24000\n";
+    size_t i;
+    unsigned int overflow_count = 0u;
+    kd_line_init(&buffer);
+    for (i = 0u; i < 200u; ++i) {
+        if (kd_line_feed(&buffer, 'x') == KD_LINE_OVERFLOW) { ++overflow_count; }
+    }
+    CHECK(overflow_count == 1u && buffer.discarding);
+    /* An apparent valid suffix is still discarded with the oversized line. */
+    for (i = 0u; valid[i] != '\0'; ++i) {
+        CHECK(kd_line_feed(&buffer, valid[i]) == KD_LINE_NONE);
+    }
+    CHECK(!buffer.discarding);
+    for (i = 0u; valid[i] != '\0'; ++i) {
+        const kd_line_result_t result = kd_line_feed(&buffer, valid[i]);
+        CHECK(result == (valid[i] == '\n' ? KD_LINE_COMPLETE : KD_LINE_NONE));
+    }
+    CHECK(kd_parse_temperature(buffer.line, buffer.length, &frame));
+    kd_line_init(&buffer);
+    for (i = 0u; i < KD_LINE_MAX_BYTES - 1u; ++i) {
+        CHECK(kd_line_feed(&buffer, 'x') == KD_LINE_NONE);
+    }
+    CHECK(kd_line_feed(&buffer, '\n') == KD_LINE_COMPLETE);
+    CHECK(buffer.length == KD_LINE_MAX_BYTES);
+    CHECK(buffer.line[KD_LINE_MAX_BYTES] == '\0');
+    CHECK(!kd_parse_temperature(buffer.line, buffer.length, &frame));
+    for (i = 0u; i < KD_LINE_MAX_BYTES; ++i) {
+        CHECK(kd_line_feed(&buffer, 'x') == KD_LINE_NONE);
+    }
+    CHECK(kd_line_feed(&buffer, '\n') == KD_LINE_OVERFLOW);
+    CHECK(!buffer.discarding && buffer.length == 0u);
+    CHECK(kd_line_feed(&buffer, '\n') == KD_LINE_COMPLETE);
+    CHECK(buffer.length == 1u);
+}
+
+static void test_sequence_order_boot_and_wrap(void)
+{
+    kd_sequence_tracker_t tracker;
+    kd_temperature_t frame = { 7u, 10u, 100u, true, 25000, 24000 };
+    kd_sequence_init(&tracker);
+    CHECK(kd_track_temperature(&tracker, &frame) == KD_TRACK_NEW_BOOT);
+    CHECK(kd_track_temperature(&tracker, &frame) == KD_TRACK_DUPLICATE);
+    frame.seq = 9u;
+    CHECK(kd_track_temperature(&tracker, &frame) == KD_TRACK_OLD);
+    CHECK(tracker.last_seq == 10u);
+    frame.seq = 11u;
+    CHECK(kd_track_temperature(&tracker, &frame) == KD_TRACK_ACCEPTED);
+    frame.seq += 2147483648u;
+    CHECK(kd_track_temperature(&tracker, &frame) == KD_TRACK_OLD);
+    CHECK(tracker.last_seq == 11u);
+    frame.boot = 8u;
+    frame.seq = UINT32_MAX - 1u;
+    frame.uptime_ms = UINT32_MAX - 10u;
+    CHECK(kd_track_temperature(&tracker, &frame) == KD_TRACK_NEW_BOOT);
+    frame.seq = UINT32_MAX;
+    frame.uptime_ms = 10u;
+    CHECK(kd_track_temperature(&tracker, &frame) == KD_TRACK_ACCEPTED);
+    frame.seq = 0u;
+    CHECK(kd_track_temperature(&tracker, &frame) == KD_TRACK_ACCEPTED);
+    CHECK(kd_track_temperature(&tracker, &frame) == KD_TRACK_DUPLICATE);
+    frame.seq = UINT32_MAX;
+    CHECK(kd_track_temperature(&tracker, &frame) == KD_TRACK_OLD);
+    frame.seq = 1u;
+    frame.valid = false;
+    CHECK(kd_track_temperature(&tracker, &frame) == KD_TRACK_ACCEPTED);
+    frame.boot = 0u;
+    frame.seq = 0u;
+    CHECK(kd_track_temperature(&tracker, &frame) == KD_TRACK_NEW_BOOT);
+}
+
+static void test_alarm_format_and_line_roundtrip(void)
+{
+    char line[129];
+    char small[8];
+    kd_line_buffer_t buffer;
+    size_t length;
+    size_t i;
+    kd_line_init(&buffer);
+    length = kd_format_alarm(line, sizeof(line), UINT32_MAX, UINT32_MAX, 3u);
+    CHECK(length == strlen("KD1 A 4294967295 4294967295 3\n"));
+    CHECK(strcmp(line, "KD1 A 4294967295 4294967295 3\n") == 0);
+    for (i = 0u; i < length; ++i) {
+        const kd_line_result_t result = kd_line_feed(&buffer, line[i]);
+        CHECK(result == (i + 1u == length ? KD_LINE_COMPLETE : KD_LINE_NONE));
+    }
+    CHECK(buffer.length == length && strcmp(buffer.line, line) == 0);
+    CHECK(kd_format_alarm(small, sizeof(small), 1u, 1u, 0u) == 0u);
+    CHECK(small[0] == '\0');
+    CHECK(kd_format_alarm(line, sizeof(line), 0u, 0u, 4u) == 0u);
+    CHECK(line[0] == '\0');
+    CHECK(kd_format_alarm(NULL, 129u, 0u, 0u, 0u) == 0u);
+    CHECK(kd_format_alarm(line, 0u, 0u, 0u, 0u) == 0u);
+    CHECK(kd_format_alarm(line, sizeof(line), 0u, 0u, 0u) > 0u);
+    CHECK(strcmp(line, "KD1 A 0 0 0\n") == 0);
+    length = strlen(line);
+    CHECK(kd_format_alarm(line, length, 0u, 0u, 0u) == 0u);
+    CHECK(kd_format_alarm(line, length + 1u, 0u, 0u, 0u) == length);
+}
+
+int main(void)
+{
+    test_valid_boundaries_and_roundtrip();
+    test_reject_malformed_and_overflow();
+    test_partial_and_concatenated_lines();
+    test_oversize_discard_and_boundaries();
+    test_sequence_order_boot_and_wrap();
+    test_alarm_format_and_line_roundtrip();
+    puts("PASS: 6 protocol regression scenarios (40 malformed frame cases)");
+    return 0;
+}
