#define KITCHEN_PROTOCOL_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Maximum wire length includes LF (and CR, when present), excludes NUL. */
#define KD_LINE_MAX_BYTES 128u

typedef struct {
    uint32_t boot;
    uint32_t seq;
    uint32_t uptime_ms;
    bool valid;
    int32_t object_mc;
    int32_t ambient_mc;
} kd_temperature_t;

/* Exact ASCII grammar, decimal digits, one space between fields, LF/CRLF:
 * KD1 T <boot> <seq> <uptime_ms> <0|1> <object_mC> <ambient_mC>\n
 * uint32 fields reject signs. int32 fields allow minus but reject plus.
 * valid=1 additionally requires object [-70000,380000], ambient [-40000,125000].
 * valid=0 still requires int32 values; they must not be used as measurements.
 * length excludes any NUL terminator. out is unchanged on failure. */
bool kd_parse_temperature(const char *line, size_t length,
                          kd_temperature_t *out);

typedef struct {
    uint32_t boot;
    uint32_t last_seq;
    bool seen;
} kd_sequence_tracker_t;

typedef enum {
    KD_TRACK_OLD = -1,
    KD_TRACK_DUPLICATE = 0,
    KD_TRACK_ACCEPTED = 1,
    KD_TRACK_NEW_BOOT = 2
} kd_track_result_t;

void kd_sequence_init(kd_sequence_tracker_t *tracker);
/* NEW_BOOT (including first frame) and ACCEPTED consume a frame. On boot
 * change the caller must reset measurement history and retain any alarm latch.
 * Same-boot sequence uses uint32 half-range ordering; exactly half is OLD.
 * uptime_ms may wrap and is not used as the host's monotonic clock. */
kd_track_result_t kd_track_temperature(kd_sequence_tracker_t *tracker,
                                       const kd_temperature_t *frame);

typedef struct {
    char line[KD_LINE_MAX_BYTES + 1u];
    size_t length;
    bool discarding;
    bool complete;
} kd_line_buffer_t;

typedef enum {
    KD_LINE_NONE = 0,
    KD_LINE_COMPLETE,
    KD_LINE_OVERFLOW
} kd_line_result_t;

void kd_line_init(kd_line_buffer_t *buffer);
/* Feed all received bytes in order. COMPLETE exposes line and length
 * (including LF); parse immediately before feeding another byte. Long lines
 * report OVERFLOW once, then discard bytes through LF. No dynamic allocation. */
kd_line_result_t kd_line_feed(kd_line_buffer_t *buffer, char byte);

/* Write KD1 A <boot> <command_seq> <pattern>\n plus a NUL; pattern is 0..4:
 * 0 normal/silent, 1 warning, 2 alarm, 3 fault, 4 latched alarm temporarily muted.
 * Returns wire length, or zero for bad pattern/insufficient capacity. */
size_t kd_format_alarm(char *out, size_t capacity, uint32_t boot,
                       uint32_t command_seq, unsigned int pattern);

#ifdef __cplusplus
}
#endif

#endif
