int ks_wifi_info(FAR char *buf, int buflen)
{
  buf[0] = '\0';
#ifdef CONFIG_WIRELESS_WAPI
  int sock = wapi_make_socket();
  struct in_addr addr;
  if (sock < 0)
    {
      return sock;
    }

  memset(&addr, 0, sizeof(addr));
  if (wapi_get_ip(sock, KS_IF, &addr) == 0)
    {
      snprintf(buf, buflen, "%s", inet_ntoa(addr));
    }

  close(sock);
#endif
  return buf[0] ? 0 : -1;
}

