#define KITCHEN_NETWORK_H

#include <stdbool.h>
#include <stdint.h>

#include "kitchen_protocol.h"

#ifdef __cplusplus
extern "C" {
#endif

typedef enum {
    KD_NETWORK_STOPPED = 0,
    KD_NETWORK_WIFI,
    KD_NETWORK_DHCP,
    KD_NETWORK_CONNECTING,
    KD_NETWORK_ONLINE,
    KD_NETWORK_RETRY
} kd_network_phase_t;

typedef struct {
    kd_temperature_t temperature;
    uint64_t local_monotonic_ms;
    bool new_boot;
    uint32_t generation;
} kd_network_sample_t;

typedef struct {
    bool running;
    bool tcp_connected;
    int last_error; /* Positive errno value, or zero. */
    uint32_t generation;
    uint32_t received_frames;
    uint32_t rejected_frames;
    kd_network_phase_t phase;
    char ip[16];
} kd_network_status_t;

/* Starts one detached worker. Returns 0, or a negative errno value.
 * A second call while running returns -EALREADY. No UI or LVGL calls occur
 * in the worker. WAPI/DHCP may block only that worker. */
int kd_network_start(void);

/* Nonblocking FIFO read. Frames are parsed, sequence checked and timestamped
 * on arrival. Reset risk history on generation changes and new_boot, while
 * retaining the alarm latch. Disconnect clears queued data immediately. */
bool kd_network_poll(kd_network_sample_t *out_sample);
void kd_network_status(kd_network_status_t *out_status);

/* 0 normal, 1 warning, 2 alarm, 3 fault, 4 alarm temporarily muted.
 * Call from every main-loop update; a main loop silent for 2 seconds causes
 * fault commands. The worker transmits every 500 ms. Invalid input becomes 3. */
void kd_network_set_pattern(unsigned int pattern);

uint64_t kd_network_monotonic_ms(void);

/* Asynchronous request. Does not wait on a vendor DHCP call. */
void kd_network_stop(void);

#ifdef __cplusplus
}
#endif

#endif
