static void clear_measurement_window(kitchen_risk_t *risk)
{
    risk->median_count = 0;
    risk->median_next = 0;
    risk->history_count = 0;
    risk->history_next = 0;
    risk->has_rate = false;
    risk->rate_mc_per_s = 0;
    risk->warning_pending = false;
    risk->warning_active = false;
    risk->alarm_pending = false;
    risk->cooling = false;
}

static bool advance_clock(kitchen_risk_t *risk, uint64_t now_ms)
{
    if (risk->clock_seen && now_ms < risk->now_ms) {
        return false;
    }
    risk->clock_seen = true;
    risk->now_ms = now_ms;
    return true;
}

static bool can_reset(const kitchen_risk_t *risk)
{
    return risk->has_temperature && risk->fault_flags == 0u &&
           risk->cooling &&
           risk->raw_mc < risk->config.reset_below_mc &&
           risk->filtered_mc < risk->config.reset_below_mc &&
           risk->now_ms - risk->cool_since_ms >= risk->config.reset_cool_ms;
}

static int32_t median_temperature(kitchen_risk_t *risk, int32_t value)
{
    int32_t a;
    int32_t b;
    int32_t c;
    int32_t swap;

    risk->median_samples[risk->median_next] = value;
    risk->median_next = (uint8_t)((risk->median_next + 1u) % 3u);
    if (risk->median_count < 3u) {
        ++risk->median_count;
    }
    if (risk->median_count < 3u) {
        return value;
    }
    a = risk->median_samples[0];
    b = risk->median_samples[1];
    c = risk->median_samples[2];
    if (a > b) { swap = a; a = b; b = swap; }
    if (b > c) { swap = b; b = c; c = swap; }
    if (a > b) { b = a; }
    return b;
}

static void update_rate(kitchen_risk_t *risk)
{
    const kitchen_risk_history_entry_t *reference = NULL;
    uint8_t i;

    /* Select the closest sample at least five seconds old. The time bound
     * avoids comparing a new measurement against an obsolete baseline. */
    for (i = 0; i < risk->history_count; ++i) {
        const kitchen_risk_history_entry_t *entry = &risk->history[i];
        const uint64_t age = risk->now_ms - entry->at_ms;
        if (age >= KITCHEN_RISK_RATE_WINDOW_MS &&
            age <= 2u * KITCHEN_RISK_RATE_WINDOW_MS &&
            (reference == NULL || entry->at_ms > reference->at_ms)) {
            reference = entry;
        }
    }
    risk->has_rate = reference != NULL;
    if (reference != NULL) {
        const int64_t delta_mc =
            (int64_t)risk->filtered_mc - reference->temp_mc;
        risk->rate_mc_per_s = (int32_t)(delta_mc * 1000 /
            (int64_t)(risk->now_ms - reference->at_ms));
    } else {
        risk->rate_mc_per_s = 0;
    }
    risk->history[risk->history_next].at_ms = risk->now_ms;
    risk->history[risk->history_next].temp_mc = risk->filtered_mc;
    risk->history_next = (uint8_t)((risk->history_next + 1u) %
                                  KITCHEN_RISK_HISTORY_CAPACITY);
    if (risk->history_count < KITCHEN_RISK_HISTORY_CAPACITY) {
        ++risk->history_count;
    }
}

static void update_thresholds(kitchen_risk_t *risk)
{
    bool warning_condition;

    /* The absolute alarm is independent of start/stop and fault recovery.
     * Confirmation still requires a sequence of new valid samples. */
    if (risk->filtered_mc >= risk->config.alarm_mc) {
        if (!risk->alarm_pending) {
            risk->alarm_pending = true;
            risk->alarm_since_ms = risk->now_ms;
        }
        if (risk->now_ms - risk->alarm_since_ms >=
            risk->config.alarm_hold_ms) {
            risk->alarm_latched = true;
        }
    } else {
        risk->alarm_pending = false;
    }

    warning_condition = risk->filtered_mc >= risk->config.warning_mc ||
        (risk->config.rate_warning_mc_per_s > 0 && risk->has_rate &&
         risk->rate_mc_per_s >= risk->config.rate_warning_mc_per_s);
    if (risk->started && risk->fault_flags == 0u && warning_condition) {
        if (!risk->warning_pending) {
            risk->warning_pending = true;
            risk->warning_since_ms = risk->now_ms;
        }
        risk->warning_active = risk->now_ms - risk->warning_since_ms >=
                               risk->config.warning_hold_ms;
    } else {
        risk->warning_pending = false;
        risk->warning_active = false;
    }

    if (risk->fault_flags == 0u &&
        risk->raw_mc < risk->config.reset_below_mc &&
        risk->filtered_mc < risk->config.reset_below_mc) {
        if (!risk->cooling) {
            risk->cooling = true;
            risk->cool_since_ms = risk->now_ms;
        }
    } else {
        risk->cooling = false;
    }
}

