                "vendor/allwinnertech/apps/Make.defs",
                str(BOARD / "configs/nsh_minidisplay/defconfig"),
                str(BOARD / "src/etc/init.d/rcS")]
    for relative in required:
        if not (sdk / relative).is_file():
            raise ValueError("Missing SDK file: " + str(sdk / relative))
    for name in ("Kconfig", "Makefile", "Make.defs"):
        if not (package / "s1" / name).is_file():
            raise ValueError("Missing delivered application file: " + str(package / "s1" / name))
    if not (package / "common").is_dir():
        raise ValueError("Missing common source directory.")

    build_entry = sdk / "build.sh"
    if not build_entry.is_symlink():
        if build_entry.is_file() and read_text(build_entry).strip() == "nuttx/tools/build.sh":
            raise ValueError("build.sh was extracted as symlink text. Re-extract with Linux unzip; "
                             "other SDK symlinks may also be broken.")
    elif not build_entry.exists():
        raise ValueError("Broken build.sh symlink.")

    changes = {}
    modes = {}

    def stage(path, data, mode=0o644):
        path = Path(path)
        resolved = path.resolve()
        try:
            resolved.relative_to(sdk)
        except ValueError:
            raise ValueError("Refusing to write outside SDK: " + str(path))
        if path.is_symlink():
            raise ValueError("Refusing to replace a destination symlink: " + str(path))
        if path.exists() and not path.is_file():
            raise ValueError("Destination is not a regular file: " + str(path))
        if not path.exists() or path.read_bytes() != data:
            changes[path] = data
            modes[path] = mode

    sources = {}
    for source in sorted((package / "s1").rglob("*")):
        if source.is_symlink():
            raise ValueError("Application source must not contain symlinks: " + str(source))
        if source.is_file():
            if source.suffix in (".o", ".pyc") or "__pycache__" in source.parts:
                continue
            sources[source.relative_to(package / "s1")] = source
    for source in sorted((package / "common").glob("*")):
        if source.suffix not in (".c", ".h") or not source.is_file():
            continue
        if source.is_symlink():
            raise ValueError("Common source must not be a symlink: " + str(source))
        relative = Path(source.name)
        if relative in sources:
            raise ValueError("Duplicate s1/common destination: " + str(relative))
        sources[relative] = source
    if not any(path.suffix == ".c" for path in sources):
        raise ValueError("No C source files found.")
    for relative, source in sources.items():
        stage(sdk / APP_REL / relative, source.read_bytes(), source.stat().st_mode & 0o777)

    # The shipped SDK auto-discovers app Make.defs and generates aggregate Kconfig.
    apps = sdk / APP_REL.parent
    make_defs = apps / "Make.defs"
    make_text = read_text(make_defs)
    wildcard_present = re.search(r"^\s*(?:-?include)\s+.*apps/\*/Make\.defs", make_text, re.M)
    if not wildcard_present and "apps/kitchen_demo/Make.defs" not in make_text:
        make_text = make_text.rstrip() + "\n\ninclude $(APPDIR)/vendor/allwinnertech/apps/kitchen_demo/Make.defs\n"
        stage(make_defs, make_text.encode("utf-8"))

    aggregate = apps / "Kconfig"
    aggregate_text = read_text(aggregate) if aggregate.exists() else ""
    if not aggregate_text or "This file is autogenerated, do not edit." in aggregate_text:
        child_kconfigs = {str(path.resolve()) for path in apps.glob("*/Kconfig")}
        child_kconfigs.add(str((sdk / APP_REL / "Kconfig").resolve()))
        aggregate_text = ("# This file is autogenerated, do not edit.\n"
                          "# Regenerated by " + MARKER + ".\n\n"
                          "menu \"Allwinnertech Apps\"\n" +
                          "".join('source "%s"\n' % path for path in sorted(child_kconfigs)) +
                          "endmenu # Allwinnertech Apps\n")
        stage(aggregate, aggregate_text.encode("utf-8"))
    elif not config_source_exists(aggregate_text, "kitchen_demo/Kconfig"):
        addition = '\nsource "%s"\n' % (sdk / APP_REL / "Kconfig")
        end_menu = list(re.finditer(r"^endmenu(?:\s|$)", aggregate_text, re.M))
        if end_menu:
