    if (new_boot) {
        g_shared.requested_pattern = 3;
        g_shared.pattern_updated_ms = 0;
    }
    sample = &g_shared.queue[index];
    sample->temperature = *frame;
    sample->local_monotonic_ms = now;
    sample->new_boot = new_boot;
    sample->generation = g_shared.status.generation;
    ++g_shared.queue_count;
    ++g_shared.status.received_frames;
    pthread_mutex_unlock(&g_lock);
    return true;
}

static unsigned int current_pattern(uint64_t now)
{
    unsigned int pattern;
    pthread_mutex_lock(&g_lock);
    pattern = g_shared.requested_pattern;
    if (g_shared.pattern_updated_ms == 0 ||
        now - g_shared.pattern_updated_ms >= KD_MAIN_LOOP_TIMEOUT_MS) {
        pattern = 3;
    }
    pthread_mutex_unlock(&g_lock);
    return pattern;
}

static void pause_with_stop(unsigned int milliseconds)
{
    const uint64_t deadline = kd_network_monotonic_ms() + milliseconds;
    while (!stop_requested() && kd_network_monotonic_ms() < deadline) {
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 50000000;
        nanosleep(&delay, NULL);
    }
}

