    memcpy(mac, request.ifr_hwaddr.sa_data, sizeof(mac));
    close(fd);
    dhcp = dhcpc_open(CONFIG_KITCHEN_DEMO_WIFI_IFNAME, mac, sizeof(mac));
    if (dhcp == NULL) {
