static int connect_tcp(int *out_fd)
{
    struct sockaddr_in address;
    struct pollfd waiter;
    socklen_t error_length;
    uint64_t deadline;
    int socket_error;
    int fd;
    int flags;
    int result;
    set_phase(KD_NETWORK_CONNECTING);
    fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        return errno;
    }
    flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0 || fcntl(fd, F_SETFL, flags | O_NONBLOCK) < 0) {
        socket_error = errno;
        close(fd);
        return socket_error;
    }
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_port = htons(KD_NETWORK_SERVER_PORT);
    if (inet_pton(AF_INET, KD_NETWORK_SERVER_ADDRESS, &address.sin_addr) != 1) {
        close(fd);
        return EINVAL;
    }
    result = connect(fd, (struct sockaddr *)&address, sizeof(address));
    if (result == 0) {
        *out_fd = fd;
        return 0;
    }
    if (errno != EINPROGRESS && errno != EWOULDBLOCK) {
        socket_error = errno;
        close(fd);
        return socket_error;
    }
    deadline = kd_network_monotonic_ms() + KD_CONNECT_TIMEOUT_MS;
    waiter.fd = fd;
    waiter.events = POLLOUT;
    while (!stop_requested() && kd_network_monotonic_ms() < deadline) {
        waiter.revents = 0;
        result = poll(&waiter, 1, 50);
        if (result < 0) {
            if (errno == EINTR) {
                continue;
            }
            socket_error = errno;
            close(fd);
            return socket_error;
        }
        if (result == 0) {
            continue;
        }
        socket_error = 0;
        error_length = sizeof(socket_error);
        if (getsockopt(fd, SOL_SOCKET, SO_ERROR, &socket_error,
                       &error_length) < 0) {
            socket_error = errno;
        }
        if (socket_error != 0 || !(waiter.revents & POLLOUT)) {
            close(fd);
            return socket_error != 0 ? socket_error : ECONNABORTED;
        }
        *out_fd = fd;
        return 0;
    }
    close(fd);
    return stop_requested() ? ECANCELED : ETIMEDOUT;
}

static int stream_samples(int fd, kd_sequence_tracker_t *tracker)
{
    kd_line_buffer_t line;
    uint64_t last_fresh_ms = kd_network_monotonic_ms();
    uint64_t last_command_ms = 0;
    uint32_t command_sequence = 0;
    uint32_t boot = 0;
    bool have_boot = false;
    struct pollfd waiter;
    kd_line_init(&line);
    waiter.fd = fd;
    waiter.events = POLLIN;

    while (!stop_requested()) {
        uint64_t now;
        int ready;
        unsigned int receive_budget;
        waiter.revents = 0;
        ready = poll(&waiter, 1, 50);
        if (ready < 0) {
            if (errno == EINTR) {
                continue;
            }
            return errno;
        }
        if (waiter.revents & (POLLERR | POLLHUP | POLLNVAL)) {
            return ECONNRESET;
        }
        /* Limit work even when a peer floods malformed input. */
        for (receive_budget = 0;
             receive_budget < 4 && (waiter.revents & POLLIN);
             ++receive_budget) {
            char bytes[256];
            ssize_t length = recv(fd, bytes, sizeof(bytes), 0);
            ssize_t i;
            if (length == 0) {
                return ECONNRESET;
            }
            if (length < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK || errno == EINTR) {
                    break;
                }
                return errno;
            }
            for (i = 0; i < length; ++i) {
                kd_line_result_t line_result = kd_line_feed(&line, bytes[i]);
                if (line_result == KD_LINE_OVERFLOW) {
                    reject_frame();
                } else if (line_result == KD_LINE_COMPLETE) {
                    kd_temperature_t frame;
                    kd_track_result_t tracking;
                    if (!kd_parse_temperature(line.line, line.length, &frame)) {
                        reject_frame();
                        continue;
                    }
                    tracking = kd_track_temperature(tracker, &frame);
                    if (tracking != KD_TRACK_NEW_BOOT &&
                        tracking != KD_TRACK_ACCEPTED) {
                        reject_frame();
                        continue;
                    }
                    now = kd_network_monotonic_ms();
                    if (!queue_frame(&frame, now,
                                     tracking == KD_TRACK_NEW_BOOT)) {
                        return ENOBUFS;
                    }
                    last_fresh_ms = now;
                    boot = frame.boot;
                    have_boot = true;
                }
            }
        }
        now = kd_network_monotonic_ms();
        if (now - last_fresh_ms >= KD_FRESH_TIMEOUT_MS) {
            return ETIMEDOUT;
        }
        if (have_boot && now - last_command_ms >= KD_COMMAND_INTERVAL_MS) {
            char command[KD_LINE_MAX_BYTES + 1u];
            size_t length;
            ssize_t sent;
            if (command_sequence == UINT32_MAX) {
                return EOVERFLOW;
            }
            length = kd_format_alarm(command, sizeof(command), boot,
                                     ++command_sequence, current_pattern(now));
            if (length == 0) {
                return EPROTO;
            }
            sent = send(fd, command, length, MSG_NOSIGNAL);
            if (sent < 0) {
                return errno;
            }
            if ((size_t)sent != length) {
                return EIO;
            }
            last_command_ms = now;
        }
    }
    return ECANCELED;
}

static void *network_thread(void *unused)
{
    kd_sequence_tracker_t tracker;
    (void)unused;
    kd_sequence_init(&tracker);
    while (!stop_requested()) {
        int fd = -1;
        int error = join_wifi();
        if (error == 0 && !stop_requested()) {
            error = connect_tcp(&fd);
        }
        if (error == 0 && fd >= 0) {
            reset_connection_status(true, 0);
            error = stream_samples(fd, &tracker);
        }
        if (fd >= 0) {
            close(fd);
        }
        reset_connection_status(false, error);
        if (!stop_requested()) {
            pause_with_stop(KD_RETRY_INTERVAL_MS);
        }
    }
    pthread_mutex_lock(&g_lock);
    g_shared.status.running = false;
    g_shared.status.tcp_connected = false;
    g_shared.status.phase = KD_NETWORK_STOPPED;
    g_shared.queue_count = 0;
    pthread_mutex_unlock(&g_lock);
    return NULL;
}

int kd_network_start(void)
{
    pthread_t worker;
    pthread_attr_t attributes;
    struct timespec clock_check;
    int error;
    if (clock_gettime(CLOCK_MONOTONIC, &clock_check) != 0) {
        return -(errno != 0 ? errno : ENOSYS);
    }
    pthread_mutex_lock(&g_lock);
    if (g_shared.status.running) {
        pthread_mutex_unlock(&g_lock);
        return -EALREADY;
    }
    memset(&g_shared, 0, sizeof(g_shared));
    g_shared.status.running = true;
    g_shared.status.phase = KD_NETWORK_WIFI;
    g_shared.requested_pattern = 3;
    pthread_mutex_unlock(&g_lock);

    error = pthread_attr_init(&attributes);
    if (error == 0) {
        error = pthread_attr_setstacksize(&attributes, 16384);
        if (error == 0) {
            error = pthread_attr_setdetachstate(&attributes,
                                               PTHREAD_CREATE_DETACHED);
        }
        if (error == 0) {
            error = pthread_create(&worker, &attributes, network_thread, NULL);
        }
        pthread_attr_destroy(&attributes);
    }
    if (error != 0) {
        pthread_mutex_lock(&g_lock);
        g_shared.status.running = false;
        g_shared.status.phase = KD_NETWORK_STOPPED;
        g_shared.status.last_error = error;
        pthread_mutex_unlock(&g_lock);
        return -error;
    }
    return 0;
}

bool kd_network_poll(kd_network_sample_t *out_sample)
{
    if (out_sample == NULL) {
        return false;
    }
    pthread_mutex_lock(&g_lock);
    if (!g_shared.status.tcp_connected || g_shared.queue_count == 0) {
        pthread_mutex_unlock(&g_lock);
        return false;
    }
    *out_sample = g_shared.queue[g_shared.queue_head];
    g_shared.queue_head = (g_shared.queue_head + 1) % KD_QUEUE_CAPACITY;
    --g_shared.queue_count;
    pthread_mutex_unlock(&g_lock);
    return true;
}

void kd_network_status(kd_network_status_t *out_status)
{
    if (out_status == NULL) {
        return;
    }
    pthread_mutex_lock(&g_lock);
    *out_status = g_shared.status;
    pthread_mutex_unlock(&g_lock);
}

void kd_network_set_pattern(unsigned int pattern)
{
    const uint64_t now = kd_network_monotonic_ms();
    pthread_mutex_lock(&g_lock);
    g_shared.requested_pattern = pattern <= 4 ? pattern : 3;
    g_shared.pattern_updated_ms = now;
    pthread_mutex_unlock(&g_lock);
}

void kd_network_stop(void)
{
    pthread_mutex_lock(&g_lock);
    g_shared.stop_requested = true;
    pthread_mutex_unlock(&g_lock);
}
