static void receiveControl(uint32_t now) {
  if (!s1Client || !s1Client.connected()) {
    return;
  }
  for (unsigned budget = 0; budget < 256 && s1Client.available(); ++budget) {
    const int byteValue = s1Client.read();
    if (byteValue < 0) {
      break;
    }
    const char byte = static_cast<char>(byteValue);
    if (byte == '\n') {
      if (discardReceiveLine) {
        rejectFrame(now);
      } else {
        receiveLine[receiveLength] = '\0';
        handleControlLine(now);
      }
      receiveLength = 0;
      discardReceiveLine = false;
    } else if (!discardReceiveLine) {
      if (receiveLength >= sizeof(receiveLine) - 1 || byte < 32 || byte > 126) {
        discardReceiveLine = true;
        receiveLength = 0;
      } else {
        receiveLine[receiveLength++] = byte;
      }
    }
  }
}

static void queueSample(uint32_t now) {
  if (!s1Client || !s1Client.connected() || transmitLength != 0) {
    return;
  }
  const int length = snprintf(
      transmitLine, sizeof(transmitLine), "KD1 T %lu %lu %lu %u %ld %ld\n",
      static_cast<unsigned long>(bootId),
      static_cast<unsigned long>(sampleSequence),
      static_cast<unsigned long>(now), sensorValid ? 1U : 0U,
      static_cast<long>(objectMC), static_cast<long>(ambientMC));
  if (length <= 0 || static_cast<size_t>(length) >= sizeof(transmitLine)) {
    return;
  }
  transmitLength = static_cast<size_t>(length);
  transmitOffset = 0;
  transmitStartedAt = now;
}

static void flushSample(uint32_t now) {
  if (transmitLength == 0 || !s1Client || !s1Client.connected()) {
    return;
  }
  if (elapsed(now, transmitStartedAt, TRANSMIT_TIMEOUT_MS)) {
    disconnectS1("send stalled");
    return;
  }
  // A stalled receiver must not block local alarm timing.
  const int sent = ::send(s1Client.fd(), transmitLine + transmitOffset,
                          transmitLength - transmitOffset, MSG_DONTWAIT);
  if (sent > 0) {
    transmitOffset += static_cast<size_t>(sent);
    if (transmitOffset == transmitLength) {
      transmitLength = 0;
      transmitOffset = 0;
    }
  } else if (sent == 0 ||
             (errno != EAGAIN && errno != EWOULDBLOCK && errno != EINTR)) {
    disconnectS1("send failed");
  }
}

