                          bool lastField) {
  if (*cursor < '0' || *cursor > '9') {
    return false;
  }
  uint32_t value = 0;
  while (*cursor >= '0' && *cursor <= '9') {
    const uint32_t digit = static_cast<uint32_t>(*cursor - '0');
    if (value > (UINT32_MAX - digit) / 10U) {
      return false;
    }
    value = value * 10U + digit;
    ++cursor;
  }
  if (lastField) {
    if (*cursor != '\0') {
      return false;
    }
  } else {
    if (*cursor != ' ') {
      return false;
    }
    ++cursor;
  }
