static unsigned int output_pattern(const kitchen_risk_snapshot_t *snapshot)
{
  if (snapshot->alarm_latched)
    return snapshot->muted && !snapshot->fault_flags ? 4 : 2;
  if (snapshot->fault_flags != 0)
    return 3;
  if (snapshot->state == KITCHEN_RISK_WARNING)
    return 1;
  return 0;
}

static void render_snapshot(const kitchen_risk_snapshot_t *snapshot,
                            const kd_network_status_t *network)
{
  char text[96];
  if (snapshot->measurement_healthy)
    {
      int32_t value = snapshot->filtered_mc;
      uint32_t magnitude = (uint32_t)(value < 0 ? -value : value);
      snprintf(text, sizeof(text), "%s%lu.%lu C", value < 0 ? "-" : "",
               (unsigned long)(magnitude / 1000),
               (unsigned long)((magnitude % 1000) / 100));
      lv_label_set_text(g_temperature, text);
    }
  else
    lv_label_set_text(g_temperature, "--.- C");

  lv_color_t color = lv_color_hex(0x304846);
  const char *state = kitchen_risk_state_name(snapshot->state);
  if (snapshot->alarm_latched)
    { state = "HIGH TEMP"; color = lv_color_hex(0xb52435); }
  else if (snapshot->fault_flags)
    { state = "DATA FAULT"; color = lv_color_hex(0xb52435); }
  else if (snapshot->state == KITCHEN_RISK_WARNING)
    { state = "WARNING"; color = lv_color_hex(0x926800); }
  else if (snapshot->started)
    state = "MONITORING";
  lv_label_set_text(g_state, state);
  lv_obj_set_style_text_color(g_state, color, 0);
  lv_label_set_text(g_detail, snapshot->fault_flags ? "CHECK SENSOR/LINK" :
                    snapshot->muted ? "MUTED 30s" :
                    snapshot->alarm_latched ? "ACK REQUIRED" : "LIVE READING");
  if (snapshot->has_rate && snapshot->measurement_healthy)
    {
      int32_t rate = snapshot->rate_mc_per_s;
      uint32_t magnitude = (uint32_t)(rate < 0 ? -rate : rate);
      snprintf(text, sizeof(text), "Trend: %s%lu.%02lu C/s", rate < 0 ? "-" : "+",
               (unsigned long)(magnitude / 1000),
               (unsigned long)((magnitude % 1000) / 10));
      lv_label_set_text(g_rate, text);
    }
  else
    lv_label_set_text(g_rate, "Trend: -- C/s");
  snprintf(text, sizeof(text), "LIVE | %s | #%lu",
           network->tcp_connected ? "CONNECTED" : "CONNECTING",
           (unsigned long)network->received_frames);
  lv_label_set_text(g_link, text);
  lv_label_set_text(g_start_label, snapshot->started ? LV_SYMBOL_PAUSE " STOP" :
                    LV_SYMBOL_PLAY " START");
  if (snapshot->reset_allowed && snapshot->alarm_latched)
    lv_obj_remove_state(g_reset_button, LV_STATE_DISABLED);
  else
    lv_obj_add_state(g_reset_button, LV_STATE_DISABLED);
  if (!network->tcp_connected)
    snprintf(text, sizeof(text), "ESP32 AP: KitchenDemo  error:%d", network->last_error);
  else if (snapshot->fault_flags)
    snprintf(text, sizeof(text), "No fresh valid reading. Check GY-906.");
  else if (snapshot->alarm_latched)
    snprintf(text, sizeof(text), "%s", snapshot->reset_allowed ?
             "Cooled down. RESET is available." : "RESET: below 32C for 5 seconds");
  else
    snprintf(text, sizeof(text), "Real sensor / low-temperature demo");
  lv_label_set_text(g_footer, text);
}

