  }
  const uint32_t phase = static_cast<uint32_t>(now - patternStartedAt);
  bool on = false;
  switch (effectivePattern) {
    case 0:
    case 4:
      break;
    case 1:
      on = (phase % 2000) < 120;
      break;
    case 2:
      on = true;
      break;
    case 3: {
      const uint32_t cycle = phase % 4000;
