int kitchen_demo_main(int argc, FAR char *argv[])
{
  kitchen_risk_config_t config;
  lv_nuttx_dsc_t descriptor;
  lv_nuttx_result_t result;
  (void)argc;
  (void)argv;
  if (lv_is_initialized())
    {
      fprintf(stderr, "kitchen_demo: another LVGL app is running; reboot with the demo config\n");
      return 1;
    }
  kitchen_risk_default_config(&config);
  if (!kitchen_risk_init(&g_risk, &config))
    return 1;
  lv_init();
  lv_nuttx_dsc_init(&descriptor);
  memset(&result, 0, sizeof(result));
#ifdef CONFIG_LV_USE_NUTTX_LCD
  descriptor.fb_path = "/dev/lcd0";
#endif
#ifdef CONFIG_LV_USE_NUTTX_TOUCHSCREEN
#ifdef CONFIG_EXAMPLES_LVGLDEMO_INPUT_DEVPATH
  descriptor.input_path = CONFIG_EXAMPLES_LVGLDEMO_INPUT_DEVPATH;
#else
  descriptor.input_path = "/dev/input0";
#endif
#endif
  lv_nuttx_init(&descriptor, &result);
  if (result.disp == NULL)
    {
      fprintf(stderr, "kitchen_demo: display init failed\n");
      return 1;
    }
  int width = lv_display_get_horizontal_resolution(result.disp);
  int height = lv_display_get_vertical_resolution(result.disp);
  if (width == 240 && height == 320)
    {
      lv_display_set_rotation(result.disp, LV_DISPLAY_ROTATION_90);
      width = lv_display_get_horizontal_resolution(result.disp);
      height = lv_display_get_vertical_resolution(result.disp);
    }
  if (width < 300 || height < 230)
    {
      fprintf(stderr, "kitchen_demo: requires landscape display >=300x230; got %dx%d\n", width, height);
      lv_nuttx_deinit(&result);
      return 1;
    }
  build_screen(width, height);
  int ret = kd_network_start();
  if (ret < 0)
    {
      fprintf(stderr, "kitchen_demo: network start failed %d\n", ret);
      lv_nuttx_deinit(&result);
      return 1;
    }
  printf("KITCHEN_DEMO_V1 live=1 warning_mc=35000 alarm_mc=45000 reset_mc=32000\n");
  printf("local_ms,source,seq,raw_mc,filtered_mc,rate_mc_s,state,fault,pattern\n");
  for (;;)
    {
      kd_network_status_t network;
      kd_network_sample_t sample;
      kitchen_risk_snapshot_t snapshot;
      uint64_t now = kd_network_monotonic_ms();
      kd_network_status(&network);
      if (network.generation != g_generation)
        {
          g_generation = network.generation;
          kitchen_risk_source_reset(&g_risk, now);
        }
      /* Consume one frame per iteration so distinct frames never acquire
       * the same processing timestamp. Discard delayed queue contents. */
      bool got_sample = kd_network_poll(&sample);
      now = kd_network_monotonic_ms();
      if (got_sample)
        {
          if (sample.generation != g_generation || sample.new_boot)
            {
              g_generation = sample.generation;
              kitchen_risk_source_reset(&g_risk, now);
            }
          if (now >= sample.local_monotonic_ms &&
              now - sample.local_monotonic_ms < 1000)
            kitchen_risk_sample(&g_risk, now, sample.temperature.object_mc,
                                sample.temperature.valid);
          else
            kitchen_risk_source_reset(&g_risk, now);
        }
      kitchen_risk_tick(&g_risk, now);
      kitchen_risk_snapshot(&g_risk, &snapshot);
      unsigned int pattern = output_pattern(&snapshot);
      kd_network_set_pattern(pattern);
      render_snapshot(&snapshot, &network);
      if (got_sample || now - g_last_log_ms >= 1000)
        {
          printf("%" PRIu64 ",live,%lu,%ld,%ld,%ld,%s,%lu,%u\n", now,
                 got_sample ? (unsigned long)sample.temperature.seq : 0ul,
                 (long)snapshot.raw_mc, (long)snapshot.filtered_mc,
                 (long)snapshot.rate_mc_per_s,
                 kitchen_risk_state_name(snapshot.state),
                 (unsigned long)snapshot.fault_flags, pattern);
          g_last_log_ms = now;
        }
      uint32_t idle = lv_timer_handler();
      if (idle > 20)
        idle = 20;
      usleep(idle ? idle * 1000 : 1000);
    }
  return 0;
}
"}

