static void command_event(lv_event_t *event)
{
  kitchen_risk_snapshot_t snapshot;
  uintptr_t command = (uintptr_t)lv_event_get_user_data(event);
  uint64_t now = kd_network_monotonic_ms();
  kitchen_risk_snapshot(&g_risk, &snapshot);
  if (command == 0)
    {
      if (snapshot.started)
        kitchen_risk_stop(&g_risk, now);
      else
        kitchen_risk_start(&g_risk, now);
    }
  else if (command == 1)
    kitchen_risk_mute(&g_risk, now);
  else
    (void)kitchen_risk_reset(&g_risk, now);
}

static lv_obj_t *button_at(lv_obj_t *parent, int x, int y, int width,
                           const char *text, uintptr_t command)
{
  lv_obj_t *button = lv_button_create(parent);
  lv_obj_set_pos(button, x, y);
  lv_obj_set_size(button, width, 34);
  lv_obj_set_style_radius(button, 4, 0);
  lv_obj_set_style_bg_color(button, lv_color_hex(0x304846), 0);
  lv_obj_add_event_cb(button, command_event, LV_EVENT_CLICKED, (void *)command);
  lv_obj_t *label = lv_label_create(button);
  lv_label_set_text(label, text);
  lv_obj_center(label);
  if (command == 0)
    g_start_label = label;
  return button;
}

