  lv_obj_set_style_text_font(g_temperature, &lv_font_montserrat_28, 0);
#endif
  g_state = label_at(screen, width / 2 + 6, 56, width / 2 - 14, "WAITING");
  g_detail = label_at(screen, width / 2 + 6, 80, width / 2 - 14, "NO DATA");
  g_rate = label_at(screen, 8, 108, width - 16, "Trend: -- C/s");
  label_at(screen, 8, 132, width - 16, "DEMO: warn 35C / alarm 45C");
  button_at(screen, 8, buttons_y, column, LV_SYMBOL_PLAY " START", 0);
  button_at(screen, 12 + column, buttons_y, column, LV_SYMBOL_MUTE " 30s", 1);
  g_reset_button = button_at(screen, 16 + 2 * column, buttons_y, column,
                             LV_SYMBOL_REFRESH " RESET", 2);
  g_footer = label_at(screen, 8, height - 33, width - 16,
                      "Waiting for real sensor data");
}

static unsigned int output_pattern(const kitchen_risk_snapshot_t *snapshot)
{
  if (snapshot->alarm_latched)
    return snapshot->muted && !snapshot->fault_flags ? 4 : 2;
  if (snapshot->fault_flags != 0)
    return 3;
  if (snapshot->state == KITCHEN_RISK_WARNING)
    return 1;
  return 0;
}

static void render_snapshot(const kitchen_risk_snapshot_t *snapshot,
                            const kd_network_status_t *network)
{
  char text[96];
  if (snapshot->measurement_healthy)
    {
      int32_t value = snapshot->filtered_mc;
      uint32_t magnitude = (uint32_t)(value < 0 ? -value : value);
      snprintf(text, sizeof(text), "%s%lu.%lu C", value < 0 ? "-" : "",
               (unsigned long)(magnitude / 1000),
               (unsigned long)((magnitude % 1000) / 100));
      lv_label_set_text(g_temperature, text);
    }
  else
    lv_label_set_text(g_temperature, "--.- C");

  lv_color_t color = lv_color_hex(0x304846);
  const char *state = kitchen_risk_state_name(snapshot->state);
  if (snapshot->alarm_latched)
    { state = "HIGH TEMP"; color = lv_color_hex(0xb52435); }
  else if (snapshot->fault_flags)
    { state = "DATA FAULT"; color = lv_color_hex(0xb52435); }
  else if (snapshot->state == KITCHEN_RISK_WARNING)
    { state = "WARNING"; color = lv_color_hex(0x926800); }
  else if (snapshot->started)
    state = "MONITORING";
  lv_label_set_text(g_state, state);
  lv_obj_set_style_text_color(g_state, color, 0);
  lv_label_set_text(g_detail, snapshot->fault_flags ? "CHECK SENSOR/LINK" :
                    snapshot->muted ? "MUTED 30s" :
                    snapshot->alarm_latched ? "ACK REQUIRED" : "LIVE READING");
  if (snapshot->has_rate && snapshot->measurement_healthy)
    {
      int32_t rate = snapshot->rate_mc_per_s;
      uint32_t magnitude = (uint32_t)(rate < 0 ? -rate : rate);
      snprintf(text, sizeof(text), "Trend: %s%lu.%02lu C/s", rate < 0 ? "-" : "+",
               (unsigned long)(magnitude / 1000),
               (unsigned long)((magnitude % 1000) / 10));
      lv_label_set_text(g_rate, text);
    }
  else
    lv_label_set_text(g_rate, "Trend: -- C/s");
  snprintf(text, sizeof(text), "LIVE | %s | #%lu",
           network->tcp_connected ? "CONNECTED" : "CONNECTING",
           (unsigned long)network->received_frames);
  lv_label_set_text(g_link, text);
  lv_label_set_text(g_start_label, snapshot->started ? LV_SYMBOL_PAUSE " STOP" :
                    LV_SYMBOL_PLAY " START");
  if (snapshot->reset_allowed && snapshot->alarm_latched)
    lv_obj_remove_state(g_reset_button, LV_STATE_DISABLED);
  else
    lv_obj_add_state(g_reset_button, LV_STATE_DISABLED);
  if (!network->tcp_connected)
    snprintf(text, sizeof(text), "ESP32 AP: KitchenDemo  error:%d", network->last_error);
  else if (snapshot->fault_flags)
    snprintf(text, sizeof(text), "No fresh valid reading. Check GY-906.");
  else if (snapshot->alarm_latched)
    snprintf(text, sizeof(text), "%s", snapshot->reset_allowed ?
             "Cooled down. RESET is available." : "RESET: below 32C for 5 seconds");
  else
    snprintf(text, sizeof(text), "Real sensor / low-temperature demo");
  lv_label_set_text(g_footer, text);
}

int kitchen_demo_main(int argc, FAR char *argv[])
{
  kitchen_risk_config_t config;
  lv_nuttx_dsc_t descriptor;
  lv_nuttx_result_t result;
  (void)argc;
  (void)argv;
  if (lv_is_initialized())
    {
      fprintf(stderr, "kitchen_demo: another LVGL app is running; reboot with the demo config\n");
      return 1;
    }
  kitchen_risk_default_config(&config);
  if (!kitchen_risk_init(&g_risk, &config))
    return 1;
  lv_init();
  lv_nuttx_dsc_init(&descriptor);
  memset(&result, 0, sizeof(result));
#ifdef CONFIG_LV_USE_NUTTX_LCD
  descriptor.fb_path = "/dev/lcd0";
#endif
#ifdef CONFIG_LV_USE_NUTTX_TOUCHSCREEN
#ifdef CONFIG_EXAMPLES_LVGLDEMO_INPUT_DEVPATH
  descriptor.input_path = CONFIG_EXAMPLES_LVGLDEMO_INPUT_DEVPATH;
#else
  descriptor.input_path = "/dev/input0";
#endif
#endif
  lv_nuttx_init(&descriptor, &result);
  if (result.disp == NULL)
    {
      fprintf(stderr, "kitchen_demo: display init failed\n");
      return 1;
    }
  int width = lv_display_get_horizontal_resolution(result.disp);
  int height = lv_display_get_vertical_resolution(result.disp);
  if (width == 240 && height == 320)
    {
      lv_display_set_rotation(result.disp, LV_DISPLAY_ROTATION_90);
      width = lv_display_get_horizontal_resolution(result.disp);
      height = lv_display_get_vertical_resolution(result.disp);
    }
  if (width < 300 || height < 230)
    {
      fprintf(stderr, "kitchen_demo: requires landscape display >=300x230; got %dx%d\n", width, height);
      lv_nuttx_deinit(&result);
      return 1;
    }
  build_screen(width, height);
  int ret = kd_network_start();
  if (ret < 0)
    {
      fprintf(stderr, "kitchen_demo: network start failed %d\n", ret);
      lv_nuttx_deinit(&result);
      return 1;
    }
  printf("KITCHEN_DEMO_V1 live=1 warning_mc=35000 alarm_mc=45000 reset_mc=32000\n");
  printf("local_ms,source,seq,raw_mc,filtered_mc,rate_mc_s,state,fault,pattern\n");
  for (;;)
    {
      kd_network_status_t network;
      kd_network_sample_t sample;
      kitchen_risk_snapshot_t snapshot;
      uint64_t now = kd_network_monotonic_ms();
      kd_network_status(&network);
      if (network.generation != g_generation)
        {
          g_generation = network.generation;
          kitchen_risk_source_reset(&g_risk, now);
        }
      /* Consume one frame per iteration so distinct frames never acquire
       * the same processing timestamp. Discard delayed queue contents. */
      bool got_sample = kd_network_poll(&sample);
      now = kd_network_monotonic_ms();
      if (got_sample)
        {
          if (sample.generation != g_generation || sample.new_boot)
            {
              g_generation = sample.generation;
              kitchen_risk_source_reset(&g_risk, now);
            }
          if (now >= sample.local_monotonic_ms &&
              now - sample.local_monotonic_ms < 1000)
            kitchen_risk_sample(&g_risk, now, sample.temperature.object_mc,
                                sample.temperature.valid);
          else
            kitchen_risk_source_reset(&g_risk, now);
        }
      kitchen_risk_tick(&g_risk, now);
      kitchen_risk_snapshot(&g_risk, &snapshot);
      unsigned int pattern = output_pattern(&snapshot);
      kd_network_set_pattern(pattern);
      render_snapshot(&snapshot, &network);
      if (got_sample || now - g_last_log_ms >= 1000)
        {
          printf("%" PRIu64 ",live,%lu,%ld,%ld,%ld,%s,%lu,%u\n", now,
                 got_sample ? (unsigned long)sample.temperature.seq : 0ul,
                 (long)snapshot.raw_mc, (long)snapshot.filtered_mc,
                 (long)snapshot.rate_mc_per_s,
                 kitchen_risk_state_name(snapshot.state),
                 (unsigned long)snapshot.fault_flags, pattern);
          g_last_log_ms = now;
        }
      uint32_t idle = lv_timer_handler();
      if (idle > 20)
        idle = 20;
      usleep(idle ? idle * 1000 : 1000);
    }
  return 0;
}
