    elif not config_source_exists(aggregate_text, "kitchen_demo/Kconfig"):
        addition = '\nsource "%s"\n' % (sdk / APP_REL / "Kconfig")
        end_menu = list(re.finditer(r"^endmenu(?:\s|$)", aggregate_text, re.M))
        if end_menu:
            offset = end_menu[-1].start()
            aggregate_text = aggregate_text[:offset] + addition + aggregate_text[offset:]
        else:
            aggregate_text = aggregate_text.rstrip() + addition
        stage(aggregate, aggregate_text.encode("utf-8"))

    base_config = sdk / BOARD / "configs/nsh_minidisplay"
    new_config = sdk / BOARD / "configs/kitchen_demo"
    for source in base_config.rglob("*"):
        if source.is_file() and source.name != "defconfig":
