    original = read_text(defconfig if defconfig.exists() else base_config / "defconfig")
    binary_only = re.search(r"^CONFIG_ALLWINNER_BINARY_ONLY=y$", original, re.M) is not None
    if args.autostart and binary_only:
        raise ValueError("This board uses CONFIG_ALLWINNER_BINARY_ONLY=y with a precompiled "
                         "ROMFS. rcS edits will not reliably enter the image. Install without "
                         "--autostart and start kitchen_demo from NSH, or first verify a "
                         "complete source build that regenerates ROMFS.")
    config = set_config(original, {
        "CONFIG_LUNCHER_MINI_APP": None,
        "CONFIG_KITCHEN_SMART": None,
        "CONFIG_EXAMPLES_LVGLDEMO": None,
        "CONFIG_LV_FONT_FMT_TXT_LARGE": "y",
        "CONFIG_KITCHEN_DEMO": "y",
        "CONFIG_KITCHEN_DEMO_AUTOSTART": "y" if args.autostart else None,
    })
    stage(defconfig, config.encode("utf-8"))

    if args.autostart:
        rcs = sdk / BOARD / "src/etc/init.d/rcS"
        rcs_text = read_text(rcs)
        begin = "/* BEGIN " + MARKER + " */"
        end = "/* END " + MARKER + " */"
        block = (begin + "\n#if defined(CONFIG_KITCHEN_DEMO) && defined(CONFIG_KITCHEN_DEMO_AUTOSTART)\n"
                 "kitchen_demo &\n#endif\n" + end)
        if begin in rcs_text:
            pattern = re.escape(begin) + r".*?" + re.escape(end)
            if end not in rcs_text:
                raise ValueError("Incomplete prior installer marker in rcS; inspect before continuing.")
            rcs_text = re.sub(pattern, lambda match: block, rcs_text, flags=re.S)
        else:
            rcs_text = rcs_text.rstrip() + "\n\n" + block + "\n"
        stage(rcs, rcs_text.encode("utf-8"))

    missing_driver = sdk / "vendor/allwinnertech/boards/r528/drivers/gt911_iic_touch.c"
    if not binary_only and not missing_driver.is_file():
        print("WARNING: gt911_iic_touch.c is missing. Supplement matching missing vendor sources "
              "before attempting a clean build; do not overlay old objects/Kconfig files.")
    print("SDK:", sdk)
    print("Application:", sdk / APP_REL)
    if binary_only:
        print("Board binary mode: preserved. Start kitchen_demo manually from NSH after flashing.")
    print("Planned changed files:", len(changes))
    for path in changes:
        print("  " + str(path.relative_to(sdk)))
    if args.dry_run:
        print("Dry run: no files were changed.")
        return
    if not changes:
        print("Already installed; no changes or extra backup created.")
        return

    backup = sdk / ".kitchen_demo_backups" / datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ")
    backup.mkdir(parents=True, exist_ok=False)
    manifest = {"sdk": str(sdk), "backups": [], "created": []}
    for path in changes:
        relative = path.relative_to(sdk)
        if path.exists():
            destination = backup / "files" / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, destination)
            manifest["backups"].append(str(relative))
        else:
            manifest["created"].append(str(relative))
    (backup / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    for path, data in changes.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(path.name + ".kitchen_demo_install.tmp")
        if temporary.exists() or temporary.is_symlink():
            raise ValueError("Temporary destination already exists: " + str(temporary))
        temporary.write_bytes(data)
        temporary.chmod(modes[path])
        os.replace(temporary, path)
    print("Installed. Backup and manifest:", backup)
    print("Build from the SDK root:")
    print("  ./build.sh vendor/allwinnertech/boards/r528/r528s3-gemini-s1/configs/kitchen_demo/ -j4")
    print("No build, driver changes, flashing, or SDK binary execution was performed.")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("sdk", type=Path, help="Linux SDK root containing apps/, nuttx/, vendor/.")
    parser.add_argument("--package", type=Path, default=Path(__file__).resolve().parents[1],
                        help="Delivered kitchen_demo directory (default: parent of scripts/).")
    parser.add_argument("--dry-run", action="store_true", help="Validate and print changes without writing.")
    parser.add_argument("--autostart", action="store_true",
                        help="Enable rcS autostart; rejected for precompiled board/ROMFS mode.")
    args = parser.parse_args()
    try:
        install(args)
    except (OSError, ValueError) as error:
        print("ERROR:", error, file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
