#!/bin/sh
set -eu

demo_root=$(CDPATH='' cd -- "$(dirname -- "$0")/.." && pwd)
test_build=$(mktemp -d "${TMPDIR:-/tmp}/kitchen-host.XXXXXX")
trap 'rm -rf -- "$test_build"' EXIT HUP INT TERM

cc -std=c99 -Wall -Wextra -Werror -pedantic \
  "$demo_root/common/kitchen_risk.c" "$demo_root/tests/test_risk.c" \
  -o "$test_build/test_risk"
"$test_build/test_risk"

cc -std=c99 -Wall -Wextra -Werror -pedantic \
  "$demo_root/common/kitchen_protocol.c" "$demo_root/tests/test_protocol.c" \
  -o "$test_build/test_protocol"
"$test_build/test_protocol"

# This server binds only localhost:8765, never the ESP32 access point.
cc -std=c99 -D_POSIX_C_SOURCE=200809L -Wall -Wextra -Werror -pedantic \
  -DKD_NETWORK_HOST_TEST -DKD_NETWORK_SERVER_ADDRESS='"127.0.0.1"' \
  -I"$demo_root/common" -I"$demo_root/s1" -pthread \
  "$demo_root/common/kitchen_risk.c" "$demo_root/common/kitchen_protocol.c" \
  "$demo_root/s1/kitchen_network.c" "$demo_root/tests/test_network.c" \
  -o "$test_build/test_network"
"$test_build/test_network"

