static void light_switch_event_cb(lv_event_t *e)
{
    lv_obj_t *obj = lv_event_get_target(e);
    bool state = lv_obj_has_state(obj, LV_STATE_CHECKED);
    if (state) {
        led_adapter_on();
    } else {
        led_adapter_off();
    }
    LV_LOG_USER("Light switched %s", state ? "ON" : "OFF");
}

