    /* NuttX��˳�ʼ�� */
    lv_nuttx_init(&info, &result);
    /* ��Ҫ��ʱ��Ӱ���ʼ��˳�� */
    usleep(100000);
    if (result.disp == NULL) {
        LV_LOG_ERROR("LVGL initialization failed");
        return 1;
    }
